/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'fs'

// Keywords that are recognized
const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

class Scanner {
  constructor(input) {
    this.input = input
    this.pos = 0 // current position in the input
    this.line = 1
    this.column = 1
    this.tokens = []
  }

  currentChar() {
    return this.pos < this.input.length ? this.input[this.pos] : null
  }

  peek(offset = 1) {
    const p = this.pos + offset
    return p < this.input.length ? this.input[p] : null
  }

  advance() {
    const ch = this.currentChar()
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      // Tab moves to next multiple of 4 plus 1
      this.column = Math.floor(this.column / 4) * 4 + 5
    } else {
      this.column++
    }
    this.pos++
    return ch
  }

  skipWhitespace() {
    while (this.currentChar() && /[ \t\r\n]/.test(this.currentChar())) {
      this.advance()
    }
  }

  skipLineComment() {
    // Skip until end of line or end of input
    while (this.currentChar() && this.currentChar() !== '\n') {
      this.advance()
    }
    // Don't advance past the newline; let the main loop handle it
  }

  skipBlockComment() {
    const startLine = this.line
    const startCol = this.column
    this.advance() // skip /
    this.advance() // skip *
    let depth = 1

    while (this.currentChar() && depth > 0) {
      if (this.currentChar() === '/' && this.peek() === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.currentChar() === '*' && this.peek() === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }

    if (depth > 0) {
      // Unterminated block comment
      throw {
        type: 'unterminated block comment',
        line: startLine,
        column: startCol,
      }
    }
  }

  scanString() {
    const startLine = this.line
    const startCol = this.column
    this.advance() // skip opening quote
    let result = ''

    while (this.currentChar() && this.currentChar() !== '"') {
      if (this.currentChar() === '\n') {
        throw {
          type: 'newline in string',
          line: this.line,
          column: this.column,
        }
      }

      if (this.currentChar() === '\\') {
        this.advance()
        const escapeChar = this.currentChar()
        if (!escapeChar) {
          throw {
            type: 'unterminated string',
            line: startLine,
            column: startCol,
          }
        }

        switch (escapeChar) {
          case 'n':
            result += '\n'
            this.advance()
            break
          case 't':
            result += '\t'
            this.advance()
            break
          case 'r':
            result += '\r'
            this.advance()
            break
          case '\\':
            result += '\\'
            this.advance()
            break
          case '"':
            result += '"'
            this.advance()
            break
          case '0':
            result += '\0'
            this.advance()
            break
          case 'x': {
            this.advance()
            let hex = ''
            for (let i = 0; i < 2; i++) {
              if (!/[0-9a-fA-F]/.test(this.currentChar())) {
                throw {
                  type: 'invalid escape \\' + escapeChar + (this.currentChar() || ''),
                  line: this.line,
                  column: this.column - 1,
                }
              }
              hex += this.currentChar()
              this.advance()
            }
            result += String.fromCharCode(parseInt(hex, 16))
            break
          }
          case 'u': {
            this.advance()
            if (this.currentChar() !== '{') {
              throw {
                type: 'invalid escape \\u',
                line: this.line,
                column: this.column - 2,
              }
            }
            this.advance()
            let hex = ''
            while (this.currentChar() && this.currentChar() !== '}') {
              if (!/[0-9a-fA-F]/.test(this.currentChar())) {
                throw {
                  type: 'invalid escape \\u{' + hex + this.currentChar(),
                  line: this.line,
                  column: this.column - hex.length - 3,
                }
              }
              hex += this.currentChar()
              this.advance()
            }
            if (!this.currentChar()) {
              throw {
                type: 'invalid escape \\u{' + hex,
                line: this.line,
                column: this.column - hex.length - 3,
              }
            }
            this.advance() // skip }
            const codePoint = parseInt(hex, 16)
            if (codePoint > 0x10ffff) {
              throw {
                type: 'invalid escape \\u{' + hex + '}',
                line: this.line,
                column: startCol,
              }
            }
            result += String.fromCodePoint(codePoint)
            break
          }
          default:
            throw {
              type: 'invalid escape \\' + escapeChar,
              line: this.line,
              column: this.column - 1,
            }
        }
      } else {
        result += this.currentChar()
        this.advance()
      }
    }

    if (!this.currentChar()) {
      throw {
        type: 'unterminated string',
        line: startLine,
        column: startCol,
      }
    }

    this.advance() // skip closing quote
    return JSON.stringify(result)
  }

  scanRawString() {
    const startLine = this.line
    const startCol = this.column
    this.advance() // skip r
    this.advance() // skip opening quote
    let result = ''

    while (this.currentChar() && this.currentChar() !== '"') {
      result += this.currentChar()
      this.advance()
    }

    if (!this.currentChar()) {
      throw {
        type: 'unterminated string',
        line: startLine,
        column: startCol,
      }
    }

    this.advance() // skip closing quote
    return JSON.stringify(result)
  }

  scanNumber() {
    const startPos = this.pos
    const startCol = this.column
    let text = ''

    if (this.currentChar() === '0' && this.peek() && /[xXbBoO]/.test(this.peek())) {
      text += this.currentChar()
      this.advance()
      text += this.currentChar()
      this.advance()

      const base = text[1].toLowerCase()
      const validDigits = base === 'x' ? /[0-9a-fA-F]/ : base === 'b' ? /[01]/ : /[0-7]/

      if (!validDigits.test(this.currentChar() || '')) {
        // No digit after prefix
        text += this.currentChar() || ''
        if (this.currentChar()) this.advance()
        throw {
          type: 'invalid number ' + text,
          line: this.line,
          column: startCol,
        }
      }

      while (this.currentChar() && validDigits.test(this.currentChar())) {
        text += this.currentChar()
        this.advance()
        if (this.currentChar() === '_') {
          text += this.currentChar()
          this.advance()
          if (!validDigits.test(this.currentChar() || '')) {
            throw {
              type: 'invalid number ' + text + (this.currentChar() || ''),
              line: this.line,
              column: startCol,
            }
          }
        }
      }

      // Check for invalid trailing characters
      if (this.currentChar() && /[a-zA-Z0-9_]/.test(this.currentChar())) {
        text += this.currentChar()
        this.advance()
        throw {
          type: 'invalid number ' + text,
          line: this.line,
          column: startCol,
        }
      }
    } else {
      // Decimal number
      while (this.currentChar() && /[0-9]/.test(this.currentChar())) {
        text += this.currentChar()
        this.advance()
        if (this.currentChar() === '_') {
          text += this.currentChar()
          this.advance()
          if (!this.currentChar() || !/[0-9]/.test(this.currentChar())) {
            throw {
              type: 'invalid number ' + text + (this.currentChar() || ''),
              line: this.line,
              column: startCol,
            }
          }
        }
      }

      // Optional decimal point
      if (this.currentChar() === '.' && this.peek() && /[0-9]/.test(this.peek())) {
        text += this.currentChar()
        this.advance()
        while (this.currentChar() && /[0-9]/.test(this.currentChar())) {
          text += this.currentChar()
          this.advance()
          if (this.currentChar() === '_') {
            text += this.currentChar()
            this.advance()
            if (!this.currentChar() || !/[0-9]/.test(this.currentChar())) {
              throw {
                type: 'invalid number ' + text + (this.currentChar() || ''),
                line: this.line,
                column: startCol,
              }
            }
          }
        }
      }

      // Optional exponent
      if (this.currentChar() && /[eE]/.test(this.currentChar())) {
        const eChar = this.currentChar()
        const nextChar = this.peek()
        const nextNext = this.peek(2)

        let hasDigitAfterE = false
        if (nextChar && /[0-9]/.test(nextChar)) {
          hasDigitAfterE = true
        } else if (nextChar && /[+-]/.test(nextChar) && nextNext && /[0-9]/.test(nextNext)) {
          hasDigitAfterE = true
        }

        if (!hasDigitAfterE) {
          throw {
            type: 'invalid number ' + text + eChar + (nextChar || ''),
            line: this.line,
            column: startCol,
          }
        }

        text += this.currentChar()
        this.advance()

        if (this.currentChar() && /[+-]/.test(this.currentChar())) {
          text += this.currentChar()
          this.advance()
        }

        while (this.currentChar() && /[0-9]/.test(this.currentChar())) {
          text += this.currentChar()
          this.advance()
          if (this.currentChar() === '_') {
            text += this.currentChar()
            this.advance()
            if (!this.currentChar() || !/[0-9]/.test(this.currentChar())) {
              throw {
                type: 'invalid number ' + text + (this.currentChar() || ''),
                line: this.line,
                column: startCol,
              }
            }
          }
        }
      }

      // Check for invalid trailing characters
      if (this.currentChar() && /[a-zA-Z_]/.test(this.currentChar())) {
        text += this.currentChar()
        this.advance()
        throw {
          type: 'invalid number ' + text,
          line: this.line,
          column: startCol,
        }
      }
    }

    return text
  }

  scanIdentifier() {
    let text = ''
    while (this.currentChar() && /[a-zA-Z0-9_]/.test(this.currentChar())) {
      text += this.currentChar()
      this.advance()
    }
    return text
  }

  scanPunct() {
    // Try to match longest punctuation first
    const twoChar = this.input.substring(this.pos, this.pos + 2)
    const validTwoChar = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
    if (validTwoChar.includes(twoChar)) {
      this.advance()
      this.advance()
      return twoChar
    }

    const ch = this.currentChar()
    if ('+-*/%=<>!(){}[],.;'.includes(ch)) {
      this.advance()
      return ch
    }

    return null
  }

  scan() {
    this.skipWhitespace()

    while (this.currentChar()) {
      // Check for comments
      if (this.currentChar() === '/' && this.peek() === '/') {
        this.advance()
        this.advance()
        this.skipLineComment()
        this.skipWhitespace()
        continue
      }

      if (this.currentChar() === '/' && this.peek() === '*') {
        this.skipBlockComment()
        this.skipWhitespace()
        continue
      }

      const line = this.line
      const col = this.column

      if (this.currentChar() === '"') {
        const stringBody = this.scanString()
        this.tokens.push({ kind: 'string', line, col, body: stringBody })
        this.skipWhitespace()
        continue
      }

      if (this.currentChar() === 'r' && this.peek() === '"') {
        const rawStringBody = this.scanRawString()
        this.tokens.push({ kind: 'rawstring', line, col, body: rawStringBody })
        this.skipWhitespace()
        continue
      }

      if (/[a-zA-Z_]/.test(this.currentChar())) {
        const text = this.scanIdentifier()
        const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
        this.tokens.push({ kind, line, col, body: text })
        this.skipWhitespace()
        continue
      }

      if (/[0-9]/.test(this.currentChar())) {
        const text = this.scanNumber()
        this.tokens.push({ kind: 'number', line, col, body: text })
        this.skipWhitespace()
        continue
      }

      const punct = this.scanPunct()
      if (punct) {
        this.tokens.push({ kind: 'punct', line, col, body: punct })
        this.skipWhitespace()
        continue
      }

      // Unexpected character
      throw {
        type: 'unexpected character ' + this.currentChar(),
        line,
        column: col,
      }
    }

    return this.tokens
  }
}

function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read from stdin
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch (err) {
    // Handle reading from stdin
    process.stderr.write('error: failed to read input\n')
    process.exit(2)
  }

  try {
    const scanner = new Scanner(input)
    const tokens = scanner.scan()

    if (mode === 'tokens') {
      for (const token of tokens) {
        console.log(`${token.line}:${token.col} ${token.kind} ${token.body}`)
      }
    } else if (mode === 'stats') {
      const counts = {
        ident: 0,
        keyword: 0,
        number: 0,
        punct: 0,
        rawstring: 0,
        string: 0,
      }

      for (const token of tokens) {
        counts[token.kind]++
      }

      console.log(`ident ${counts.ident}`)
      console.log(`keyword ${counts.keyword}`)
      console.log(`number ${counts.number}`)
      console.log(`punct ${counts.punct}`)
      console.log(`rawstring ${counts.rawstring}`)
      console.log(`string ${counts.string}`)
      console.log(`total ${tokens.length}`)
    }

    process.exit(0)
  } catch (err) {
    if (err.type) {
      process.stderr.write(`error: ${err.line}:${err.column}: ${err.type}\n`)
    } else {
      process.stderr.write(`error: ${err.message}\n`)
    }
    process.exit(2)
  }
}

main()
