        this.skipBlockComment()
        this.skipWhitespace()
        continue
      }

      const line = this.line
      const col = this.column

      if (this.currentChar() === '"') {
        const stringBody = this.scanString()
        this.tokens.push({ kind: 'string', line, col, body: stringBody })
