      const counts = {
        ident: 0,
        keyword: 0,
        number: 0,
        punct: 0,
        rawstring: 0,
        string: 0,
      }

      for (const token of tokens) {
        counts[token.kind]++
      }

      console.log(`ident ${counts.ident}`)
      console.log(`keyword ${counts.keyword}`)
      console.log(`number ${counts.number}`)
      console.log(`punct ${counts.punct}`)
      console.log(`rawstring ${counts.rawstring}`)
      console.log(`string ${counts.string}`)
      console.log(`total ${tokens.length}`)
    }

    process.exit(0)
  } catch (err) {
